sample_cases:
# Directory structure:
/data
├── hello.txt          # content: "red"
└── tests/
    ├── test.mp3       # content: "Hello World"
    ├── test2.mp3      # content: "Hello Not World"
    └── test3.mp3      # content: "Hey World"

# Sample request → expected result:
1. {"search_filename": "test2.mp3"}
   → {"files":["/data/tests/test2.mp3"]}
2. {"search_content": "pink"}
   → {"files":[]}
3. {"search_content": "Hey", "search_dir": "/tests"}
   → {"files":["/data/tests/test3.mp3"]}

