import { Controller, Post, Get, Query, Body, HttpCode, HttpStatus, BadRequestException } from '@nestjs/common';
import { AppService } from './app.service';
import { Click } from './click.model';
import { IsString, IsNotEmpty } from 'class-validator';
import { validate } from 'class-validator';

class RegisterClickDto {
  @IsString()
  @IsNotEmpty()
  id: string;

  @IsString()
  @IsNotEmpty()
  timestamp: string;
}

class GetClicksDto {
  @IsString()
  @IsNotEmpty()
  date: string;

  @IsString()
  @IsNotEmpty()
  direction: string;
}

@Controller('click')
export class AppController {
  constructor(private readonly appService: AppService) {}

  @Post()
  @HttpCode(HttpStatus.CREATED)
  async registerClick(@Body() click: RegisterClickDto) {
    const errors = await validate(click);
    if (errors.length > 0) {
      throw new BadRequestException('Validation failed!', errors);
    }
    return this.appService.registerClick(click);
  }

  @Get('clicks')
  async getClicks(@Query() query: GetClicksDto) {
    const errors = await validate(query);
    if (errors.length > 0) {
      throw new BadRequestException('Validation failed!', errors);
    }
    return this.appService.getClicks(query.date, query.direction);
  }
}

import { Controller, Post, Body, BadRequestException } from '@nestjs/common';
import { AppService } from './app.service';

@Controller('compile')
export class AppController {
  constructor(private readonly appService: AppService) {}

  @Post()
  async compile(@Body() body: { fileName: string; fileContent: string }) {
    const { fileName, fileContent } = body;

    // Validate inputs
    if (!fileName || !fileContent) {
      throw new BadRequestException('fileName and fileContent are required');
    }

    // Validate fileName and fileContent length
    if (fileName.length > 255 || fileContent.length > 10000) {
      throw new BadRequestException('fileName or fileContent is too long');
    }

    const result = await this.appService.compileCode(fileName, fileContent);
    return result;
  }
}

import { Controller, Post, Body, HttpCode, HttpStatus, BadRequestException } from '@nestjs/common';
import { AppService } from './app.service';
import { IsString, IsArray, validate } from 'class-validator';

class AssociateCardDto {
  @IsString()
  credit_card: string;

  @IsString()
  phone: string;
}

class RetrieveCardsDto {
  @IsArray()
  phone_numbers: string[];
}

@Controller()
export class AppController {
  constructor(private readonly appService: AppService) {}

  @Post('associate_card')
  @HttpCode(HttpStatus.CREATED)
  async associateCard(@Body() body: AssociateCardDto) {
    const errors = await validate(body);
    if (errors.length > 0) {
      throw new BadRequestException('Invalid input data');
    }
    return this.appService.associateCard(body.credit_card, body.phone);
  }

  @Post('retrieve_cards')
  @HttpCode(HttpStatus.OK)
  async retrieveCards(@Body() body: RetrieveCardsDto) {
    const errors = await validate(body);
    if (errors.length > 0) {
      throw new BadRequestException('Invalid input data');
    }
    return this.appService.retrieveCards(body.phone_numbers);
  }
}

