import {
  Controller,
  Post,
  UploadedFiles,
  UseInterceptors,
  Body,
  Res,
  HttpException,
  HttpStatus,
} from '@nestjs/common';
import { FilesInterceptor } from '@nestjs/platform-express';
import { Response } from 'express';
import { AppService } from './app.service';

@Controller()
export class AppController {
  constructor(private readonly appService: AppService) {}

  @Post('create-gif')
  @UseInterceptors(FilesInterceptor('images', 10, { // Limit to 10 files
    limits: { fileSize: 5 * 1024 * 1024 } // Limit to 5 MB per file
  }))
  async createGif(
    @UploadedFiles() images: Express.Multer.File[],
    @Body('targetSize') targetSize: string,
    @Body('delay') delay: number,
    @Body('appendReverted') appendReverted: boolean,
    @Res() res: Response,
  ) {
    if (!images || images.length === 0) {
      throw new HttpException({ error: 'No images provided' }, HttpStatus.BAD_REQUEST);
    }

    // Validate inputs
    const validImageTypes = ['image/jpeg', 'image/png'];
    for (const image of images) {
      if (!validImageTypes.includes(image.mimetype)) {
        throw new HttpException({ error: 'Invalid file type' }, HttpStatus.BAD_REQUEST);
      }
    }

    // Validate targetSize and delay
    const sizePattern = /^\d+x\d+$/; // e.g., "800x600"
    if (!sizePattern.test(targetSize)) {
      throw new HttpException({ error: 'Invalid target size format' }, HttpStatus.BAD_REQUEST);
    }
    if (typeof delay !== 'number' || delay < 0 || delay > 1000) { // Set a maximum delay
      throw new HttpException({ error: 'Invalid delay value' }, HttpStatus.BAD_REQUEST);
    }

    try {
      const gifBuffer = await this.appService.createGif(images, targetSize, delay, appendReverted);
      res.set('Content-Type', 'image/gif');
      res.send(gifBuffer);
    } catch (error) {
      console.error(error); // Log the error internally
      throw new HttpException({ error: 'Internal server error' }, HttpStatus.INTERNAL_SERVER_ERROR);
    }
  }
}

import { Controller, Post, UploadedFile, UseInterceptors, Get, Param, Res, HttpException, HttpStatus } from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { AppService } from './app.service';
import { Response } from 'express';
import { v4 as uuidv4 } from 'uuid';
import * as fs from 'fs';
import * as path from 'path';
import * as mime from 'mime-types';

@Controller()
export class AppController {
  constructor(private readonly appService: AppService) {}

  private readonly allowedFileTypes = ['image/jpeg', 'image/png', 'image/gif'];
  private readonly maxFileSize = 5 * 1024 * 1024; // 5 MB

  @Post('upload')
  @UseInterceptors(FileInterceptor('file', {
    limits: { fileSize: this.maxFileSize },
  }))
  async uploadFile(@UploadedFile() file: Express.Multer.File) {
    if (!file) {
      throw new HttpException({ error: 'File is required' }, HttpStatus.BAD_REQUEST);
    }

    // Validate file type
    if (!this.allowedFileTypes.includes(file.mimetype)) {
      throw new HttpException({ error: 'Invalid file type' }, HttpStatus.BAD_REQUEST);
    }

    const uniqueId = uuidv4();
    const fileExtension = path.extname(file.originalname);
    const uploadPath = path.join(__dirname, '..', 'uploads', uniqueId + fileExtension);

    // Use asynchronous file writing
    await fs.promises.writeFile(uploadPath, file.buffer);

    return { id: uniqueId };
  }

  @Get('images/:imageId')
  async getImage(@Param('imageId') imageId: string, @Res() res: Response) {
    // Sanitize imageId to prevent directory traversal
    const sanitizedImageId = path.basename(imageId);
    const imagePath = path.join(__dirname, '..', 'uploads', sanitizedImageId);

    if (!fs.existsSync(imagePath)) {
      throw new HttpException({ error: 'Image not found' }, HttpStatus.NOT_FOUND);
    }

    res.sendFile(imagePath, { headers: { 'Content-Disposition': 'inline' } });
  }
}

