import { Controller, Post, UploadedFiles, UseInterceptors, BadRequestException, Res } from '@nestjs/common';
import { FilesInterceptor } from '@nestjs/platform-express';
import { Response } from 'express';
import { AppService } from './app.service';
import { join, extname } from 'path';
import { promises as fs } from 'fs';
import { PDFDocument } from 'pdf-lib';

@Controller()
export class AppController {
  constructor(private readonly appService: AppService) {}

  @Post('concatenate')
  @UseInterceptors(FilesInterceptor('files'))
  async concatenatePDFs(@UploadedFiles() files: Express.Multer.File[], @Res() res: Response) {
    if (!files || files.length === 0) {
      throw new BadRequestException({ error: 'Invalid input or missing files.' });
    }

    // Validate file types and MIME types
    for (const file of files) {
      if (extname(file.originalname) !== '.pdf' || file.mimetype !== 'application/pdf') {
        throw new BadRequestException({ error: 'All files must be PDF format.' });
      }
    }

    const outputFile = join(__dirname, '..', 'output', `concatenated_${Date.now()}.pdf`);
    const pdfDoc = await PDFDocument.create();

    try {
      for (const file of files) {
        const fileData = await fs.readFile(file.path);
        const tempDoc = await PDFDocument.load(fileData);
        const copiedPages = await pdfDoc.copyPages(tempDoc, tempDoc.getPageIndices());
        copiedPages.forEach((page) => pdfDoc.addPage(page));
      }

      const pdfBytes = await pdfDoc.save();
      await fs.writeFile(outputFile, pdfBytes);

      res.download(outputFile, 'concatenated.pdf', (err) => {
        if (err) {
          throw new BadRequestException({ error: 'An error occurred while processing the files.' });
        }
      });
    } catch (error) {
      throw new BadRequestException({ error: 'An error occurred while processing the files.' });
    } finally {
      // Cleanup temporary files if necessary
      // Uncomment the following line if you want to delete uploaded files after processing
      // await Promise.all(files.map(file => fs.unlink(file.path)));
    }
  }
}

