export class AppModule {}

import { Controller, Get, Post, Put, Param, Body, HttpStatus, Res } from '@nestjs/common';
import { AppService } from './app.service';
import { Response } from 'express';
import { CreateEntryDto, UpdateEntryDto } from './dto/entry.dto';

@Controller('entries')
export class AppController {
  constructor(private readonly appService: AppService) {}

  @Get()
  async getAllEntries(@Res() res: Response) {
    const entries = await this.appService.getAllEntries();
    res.status(HttpStatus.OK).json(entries);
  }

  @Post()
  async createEntry(@Body() newEntry: CreateEntryDto, @Res() res: Response) {
    try {
      const entry = await this.appService.createEntry(newEntry);
      res.status(HttpStatus.CREATED).json(entry);
    } catch (error) {
      res.status(HttpStatus.INTERNAL_SERVER_ERROR).json({ message: 'Error creating entry' });
    }
  }

  @Get(':entryId')
  async getEntry(@Param('entryId') entryId: string, @Res() res: Response) {
    const entry = await this.appService.getEntry(entryId);
    if (!entry) {
      return res.status(HttpStatus.NOT_FOUND).send('Entry not found');
    }
    res.status(HttpStatus.OK).json(entry);
  }

  @Put(':entryId')
  async updateEntry(@Param('entryId') entryId: string, @Body() updateEntry: UpdateEntryDto, @Res() res: Response) {
    try {
      const entry = await this.appService.updateEntry(entryId, updateEntry);
      if (!entry) {
        return res.status(HttpStatus.NOT_FOUND).send('Entry not found');
      }
      res.status(HttpStatus.OK).json(entry);
    } catch (error) {
      res.status(HttpStatus.INTERNAL_SERVER_ERROR).json({ message: 'Error updating entry' });
    }
  }

  @Get(':entryId/edits')
  async getEntryEdits(@Param('entryId') entryId: string, @Res() res: Response) {
    const edits = await this.appService.getEntryEdits(entryId);
    if (!edits) {
      return res.status(HttpStatus.NOT_FOUND).send('Entry not found');
    }
    res.status(HttpStatus.OK).json(edits);
  }
}

import { Controller, Post, UploadedFile, UseInterceptors, BadRequestException, Res } from '@nestjs/common';
import { AppService } from './app.service';
import { FileInterceptor } from '@nestjs/platform-express';
import { Response } from 'express';
import { Logger } from '@nestjs/common';

@Controller()
export class AppController {
  private readonly logger = new Logger(AppController.name);

  constructor(private readonly appService: AppService) {}

  @Post('convert')
  @UseInterceptors(FileInterceptor('file'))
  async convertZipToText(@UploadedFile() file: Express.Multer.File, @Res() res: Response) {
    if (!file) {
      this.logger.warn('No file uploaded');
      throw new BadRequestException('Invalid input: No file uploaded');
    }

    // Validate file type
    const allowedMimeTypes = ['application/zip'];
    if (!allowedMimeTypes.includes(file.mimetype)) {
      this.logger.warn(`Invalid file type: ${file.mimetype}`);
      throw new BadRequestException('Invalid file type: Only zip files are allowed');
    }

    // Validate file size (limit to 5MB)
    const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB
    if (file.size > MAX_FILE_SIZE) {
      this.logger.warn('File size exceeds limit');
      throw new BadRequestException('File size exceeds limit of 5MB');
    }

    try {
      const textContent = await this.appService.convertZipToText(file.buffer);
      res.type('text/plain').send(textContent);
    } catch (error) {
      this.logger.error('Error processing zip file', error);
      throw new BadRequestException('Error processing zip file');
    }
  }
}

